class BitwiseOperations:
    def add(self, x, y):
        if x == 0 or y == 0:
            return x + y
        else:
            return self.bitwise_add(x, y)

    def subtract(self, x, y):
        if x == 0 or y == 0:
            return x - y
        else:
            return self.bitwise_subtract(x, y)

    def multiply(self, x, y):
        if x == 0 or y == 0:
            return 0
        else:
            return self.bitwise_multiply(x, y)

    def bitwise_add(self, x, y):
        # O(log N) time complexity
        if x > y:
            return (x & -x) + y
        else:
            return (y & -y) + x

    def bitwise_subtract(self, x, y):
        # O(log N) time complexity
        if x > y:
            return (x & -x) - y
        else:
            return (y & -y) - x

    def bitwise_multiply(self, x, y):
        # O(log N) time complexity
        result = 0
        for i in range(32):
            result |= (x & (1 << i)) * (y & (1 << i))
        return result
```

